def faq(id, q, a, cat, kw, steps=None, related=None, fu=None, expert=False, verify=["dae"]):
    d = {"id": id, "questionBn": q, "answerBn": a, "category": cat, "keywords": kw, "relatedIds": related or [], "followUpsBn": fu or [], "verifyWithIds": verify, **META}
    if steps: d["stepsBn"] = steps
    if expert: d["needsExpert"] = True
    return d

